class BillableResource(BaseModel):
    id: Annotated[
        str, Field(description="Unique identifier of the resource", title="Id")
    ]
    kind: Annotated[
        ResourceKind,
        Field(
            description="Resource kind (MODEL_DEPLOYMENT, TRAINING_JOB, or CHAINLET)"
        ),
    ]
    name: Annotated[
        str | None, Field(description="Name of the resource", title="Name")
    ] = None
    is_deleted: Annotated[
        bool,
        Field(
            description="Indicates if the resource has been deleted", title="Is Deleted"
        ),
    ]
    instance_type: Annotated[
        str | None, Field(description="Instance type used", title="Instance Type")
    ] = None
    environment_name: Annotated[
        str | None,
        Field(
            description="Environment name (e.g., 'production', 'staging')",
            title="Environment Name",
        ),
    ] = None
    chain_metadata: Annotated[
        ChainMetadata | None,
        Field(description="Chain metadata if this is a chainlet deployment"),
    ] = None


class DedicatedItem(BaseModel):
    billable_resource: Annotated[
        BillableResource, Field(description="The model deployment resource")
    ]
    subtotal: Annotated[
        float | Subtotal3,
        Field(
            description="Subtotal cost in dollars for this billable resource",
            title="Subtotal",
        ),
    ]
    minutes: Annotated[
        int,
        Field(
            description="Total minutes used for this billable resource", title="Minutes"
        ),
    ]
    inference_requests: Annotated[
        int,
        Field(
            description="Total inference requests for this billable resource",
            title="Inference Requests",
        ),
    ]
    daily: Annotated[
        list[DailyDedicatedUsage] | None,
        Field(description="Daily usage breakdown", title="Daily"),
    ] = None


class DedicatedUsage(BaseModel):
    subtotal: Annotated[
        float | Subtotal4,
        Field(
            description="Subtotal cost in dollars after applying credits used",
            title="Subtotal",
        ),
    ]
    credits_used: Annotated[
        float | CreditsUsed,
        Field(description="Credits applied in dollars", title="Credits Used"),
    ]
    total: Annotated[
        float | Total, Field(description="Total cost in dollars", title="Total")
    ]
    minutes: Annotated[int, Field(description="Total minutes used", title="Minutes")]
    breakdown: Annotated[
        list[DedicatedItem] | None,
        Field(description="Per-deployment usage breakdown", title="Breakdown"),
    ] = None


