class UsageSummary(BaseModel):
    dedicated_usage: Annotated[
        DedicatedUsage | None, Field(description="Dedicated model serving usage")
    ] = None
    training_usage: Annotated[
        TrainingUsage | None, Field(description="Training usage")
    ] = None
    model_apis_usage: Annotated[
        ModelApisUsage | None, Field(description="Model APIs usage")
    ] = None


class PromotionSettings(BaseModel):
    redeploy_on_promotion: Annotated[
        bool | None,
        Field(
            description="Whether to deploy on all promotions. Enabling this flag allows model code to safely handle environment-specific logic. When a deployment is promoted, a new deployment will be created with a copy of the image.",
            examples=[True],
            title="Redeploy On Promotion",
        ),
    ] = False
    rolling_deploy: Annotated[
        bool | None,
        Field(
            description="Whether the environment should rely on rolling deploy orchestration.",
            examples=[True],
            title="Rolling Deploy",
        ),
    ] = False
    promotion_cleanup_strategy: Annotated[
        PromotionCleanupStrategy | None,
        Field(
            description="The cleanup strategy to use after a promotion completes.",
            examples=["SCALE_TO_ZERO"],
        ),
    ] = PromotionCleanupStrategy.SCALE_TO_ZERO
    rolling_deploy_config: Annotated[
        RollingDeployConfig | None,
        Field(description="Rolling deploy configuration for promotions"),
    ] = None
    ramp_up_while_promoting: Annotated[
        bool | None,
        Field(
            description="Whether to ramp up traffic while promoting",
            examples=[True],
            title="Ramp Up While Promoting",
        ),
    ] = False
    ramp_up_duration_seconds: Annotated[
        int | None,
        Field(
            description="Duration of the ramp up in seconds",
            examples=[600],
            title="Ramp Up Duration Seconds",
        ),
    ] = 600


class ChainEnvironment(BaseModel):
    name: Annotated[str, Field(description="Name of the environment", title="Name")]
    created_at: Annotated[
        AwareDatetime,
        Field(
            description="Time the environment was created in ISO 8601 format",
            title="Created At",
        ),
    ]
    chain_id: Annotated[
        str, Field(description="Unique identifier of the chain", title="Chain Id")
    ]
    promotion_settings: Annotated[
        PromotionSettings, Field(description="Promotion settings for the environment")
    ]
    chainlet_settings: Annotated[
        list[ChainletEnvironmentSettings],
        Field(
            description="Environment settings for the chainlets",
            title="Chainlet Settings",
        ),
    ]
    current_deployment: Annotated[
        ChainDeployment | None,
        Field(description="Current chain deployment of the environment"),
    ]
    candidate_deployment: Annotated[
        ChainDeployment | None,
        Field(
            description="Candidate chain deployment being promoted to the environment, if a promotion is in progress"
        ),
    ] = None


class DockerAuth(BaseModel):
    registry: Annotated[
        str, Field(description="Registry to authenticate with", title="Registry")
    ]
    auth_method: Annotated[
        DockerAuthType,
        Field(
            description="Method to authenticate with the registry",
            examples=[
                "GCP_SERVICE_ACCOUNT_JSON",
                "AWS_IAM",
                "AWS_OIDC",
                "GCP_OIDC",
                "REGISTRY_SECRET",
            ],
        ),
    ]
    gcp_service_account_json_docker_auth: Annotated[
        GcpServiceAccountJsonDockerAuth | None,
        Field(description="GCP service account details for the registry"),
    ] = None
    aws_iam_docker_auth: Annotated[
        AwsIamDockerAuth | None, Field(description="AWS details for the registry")
    ] = None
    aws_oidc_docker_auth: Annotated[
        AwsOidcDockerAuth | None, Field(description="AWS OIDC details for the registry")
    ] = None
    gcp_oidc_docker_auth: Annotated[
        GcpOidcDockerAuth | None, Field(description="GCP OIDC details for the registry")
    ] = None
    registry_secret_docker_auth: Annotated[
        RegistrySecretDockerAuth | None,
        Field(
            description="Required when auth_method is REGISTRY_SECRET. Supports any Docker registry (Docker Hub, GHCR, NGC, etc.) via username:password credentials stored as a Baseten secret."
        ),
    ] = None


class Environment(BaseModel):
    name: Annotated[str, Field(description="Name of the environment", title="Name")]
    created_at: Annotated[
        AwareDatetime,
        Field(
            description="Time the environment was created in ISO 8601 format",
            title="Created At",
        ),
    ]
    model_id: Annotated[
        str, Field(description="Unique identifier of the model", title="Model Id")
    ]
    current_deployment: Annotated[
        Deployment | None, Field(description="Current deployment of the environment")
    ]
    candidate_deployment: Annotated[
        Deployment | None,
        Field(
            description="Candidate deployment being promoted to the environment, if a promotion is in progress"
        ),
    ] = None
    in_progress_promotion: Annotated[
        InProgressPromotion | None,
        Field(description="Details of the in-progress promotion, if any"),
    ] = None
    autoscaling_settings: Annotated[
        AutoscalingSettings,
        Field(description="Autoscaling settings for the environment"),
    ]
    promotion_settings: Annotated[
        PromotionSettings, Field(description="Promotion settings for the environment")
    ]
    instance_type: Annotated[
        InstanceType, Field(description="Instance type for the environment")
    ]


class Environments(BaseModel):
    environments: Annotated[list[Environment], Field(title="Environments")]


class CreateTrainingJobImage(BaseModel):
    base_image: Annotated[
        str,
        Field(
            description="Base image for the training job.",
            examples=["hello-world"],
            title="Base Image",
        ),
    ]
    docker_auth: Annotated[
        DockerAuth | None, Field(description="Docker authentication credentials")
    ] = None


class CreateTrainingJob(BaseModel):
    image: Annotated[
        CreateTrainingJobImage,
        Field(examples=[{"base_image": "hello-world", "docker_auth": None}]),
    ]
    compute: Annotated[
        CreateTrainingJobCompute | None,
        Field(
            examples=[
                {
                    "accelerator": {"accelerator": "H100", "count": 2},
                    "cpu_count": 1,
                    "memory": "2Gi",
                    "node_count": 1,
                }
            ]
        ),
    ] = None
    runtime: Annotated[
        CreateTrainingJobRuntime | None,
        Field(
            description="Configuration for the runtime environment of the training job.",
            examples=[
                {
                    "artifacts": [],
                    "cache_config": None,
                    "checkpointing_config": {
                        "checkpoint_path": None,
                        "enabled": False,
                        "volume_size_gib": None,
                    },
                    "enable_cache": None,
                    "environment_variables": {
                        "API_KEY": "your_api_key_here",
                        "PATH": "/usr/bin",
                    },
                    "load_checkpoint_config": None,
                    "start_commands": ["python main.py"],
                }
            ],
        ),
    ] = None
    name: Annotated[
        str | None,
        Field(
            description="Name of the training job.",
            examples=["gpt-oss-job"],
            title="Name",
        ),
    ] = None
    truss_user_env: Annotated[
        TrussUserEnv | None, Field(description="Truss user environment information")
    ] = None
    interactive_session: Annotated[
        InteractiveSessionConfig | None,
        Field(description="Configuration for interactive debugging sessions."),
    ] = None
    weights: Annotated[
        list[CreateJobWeightConfig] | None,
        Field(
            description="MDN weight sources to mount in the training container. Weights are mirrored and cached for fast startup.",
            examples=[
                [
                    {
                        "allow_patterns": None,
                        "auth": None,
                        "auth_secret_name": None,
                        "ignore_patterns": None,
                        "mount_location": "/app/models/base",
                        "source": "hf://meta-llama/Llama-3-8B@main",
                    }
                ]
            ],
            title="Weights",
        ),
    ] = None


class CreateTrainingJobRequest(BaseModel):
    training_job: Annotated[
        CreateTrainingJob, Field(description="The training job to create.")
    ]
